// The chat line types. A dispatcher picks one by event type and, for notices,
// by msg-id. Most types are small: an icon, the server's system message and
// sometimes the user's own tokenized message.
import { Component, type ComponentType, type ReactNode } from "react";
import { CoreText, Layout, SvgIcon, type IconName } from "../core-ui";
import { CheerFragment, Emote, LinkFragment, MentionFragment } from "./fragments";
import { MessageLine } from "./message-line";
import type { LineProps } from "./line-props";
import { ChatEventType, MessagePartType, type ChatMessageEvent, type ChatNoticeEvent, type MessagePart } from "./types";

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type AnyLine = ComponentType<any>;

class LineErrorBoundary extends Component<{ children: ReactNode }, { failed: boolean }> {
  state = { failed: false };
  static getDerivedStateFromError() {
    return { failed: true };
  }
  render() {
    return this.state.failed ? null : this.props.children;
  }
}

export function MessageParts({ parts }: { parts: MessagePart[] }) {
  return (
    <>
      {parts.map((part, i) => {
        switch (part.type) {
          case MessagePartType.Text:
            return (
              <span key={i} className="text-fragment" data-a-target="chat-message-text">
                {part.content}
              </span>
            );
          case MessagePartType.Mention:
            return <MentionFragment key={i} recipient={part.content.recipient} relation={part.content.currentUserMentionRelation} />;
          case MessagePartType.Link:
            return <LinkFragment key={i} url={part.content.url} text={part.content.displayText} onLinkClick={() => {}} />;
          case MessagePartType.Emote:
            return <Emote key={i} alt={part.content.alt} emoteID={part.content.emoteID} images={part.content.images} />;
          case MessagePartType.Cheer:
            return <CheerFragment key={i} part={part} />;
          default:
            return null;
        }
      })}
    </>
  );
}

interface SystemLineOptions {
  icon: IconName;
  modifier: string;
  accent?: boolean;
  text?: (e: ChatNoticeEvent) => string;
}

function defaultText(e: ChatNoticeEvent): string {
  return e.systemMessage || (e.user ? e.user.displayName : "");
}

/** Creates a named line component: a notice with an icon, text and optional user message. */
function systemLine(displayName: string, { icon, modifier, accent, text = defaultText }: SystemLineOptions): AnyLine {
  const Line = ({ message }: LineProps<ChatNoticeEvent>) => (
    <Layout padding={{ x: 1, y: 0.5 }} className="user-notice-line">
      <Layout className={`user-notice-line__inner user-notice-line--${modifier}${accent ? " user-notice-line--accent" : ""}`} data-a-target="chat-user-notice" data-test-selector="user-notice-line" padding={{ left: 1 }}>
        <Layout display="flex" alignItems="center">
          <Layout flexShrink={0} margin={{ right: 0.5 }}>
            <SvgIcon name={icon} size={16} />
          </Layout>
          <CoreText $fontSize={6} $color="alt" $bold>
            {text(message)}
          </CoreText>
        </Layout>
        {message.messageParts && message.messageParts.length > 0 ? (
          <Layout className="user-notice-line__message" padding={{ top: 0.5 }}>
            {message.user ? (
              <span className="chat-author__display-name" style={{ color: message.user.color }}>
                {message.user.displayName}
                <span aria-hidden="true">: </span>
              </span>
            ) : null}
            <span data-a-target="chat-line-message-body" dir="auto">
              <MessageParts parts={message.messageParts} />
            </span>
          </Layout>
        ) : null}
      </Layout>
    </Layout>
  );
  Line.displayName = displayName;
  return Line;
}

const SubscriptionLine = systemLine("SubscriptionLine", { icon: "star", modifier: "subscription", accent: true });
const ResubscriptionLine = systemLine("ResubscriptionLine", { icon: "star", modifier: "resubscription", accent: true });
const SubGiftLine = systemLine("SubGiftLine", { icon: "gift", modifier: "subgift", accent: true });
const SubMysteryGiftLine = systemLine("SubMysteryGiftLine", { icon: "gift", modifier: "submysterygift", accent: true });
const GiftPaidUpgradeLine = systemLine("GiftPaidUpgradeLine", { icon: "gift", modifier: "giftpaidupgrade", accent: true });
const RaidLine = systemLine("RaidLine", { icon: "raid", modifier: "raid", accent: true });
const AnnouncementLine = systemLine("AnnouncementLine", { icon: "announce", modifier: "announcement", accent: true, text: () => "Announcement" });
const BitsBadgeTierMessage = systemLine("BitsBadgeTierMessage", { icon: "bits", modifier: "bitsbadgetier", accent: true });
const RitualLine = systemLine("RitualLine", { icon: "heart", modifier: "ritual" });
const NoticeLine = systemLine("NoticeLine", { icon: "info", modifier: "notice" });
const ChatClearedLine = systemLine("ChatClearedLine", { icon: "moderation", modifier: "cleared", text: () => "Chat was cleared by a moderator" });
const RoomModsLine = systemLine("RoomModsLine", { icon: "moderation", modifier: "roommods" });
const SlowModeLine = systemLine("SlowModeLine", { icon: "clock", modifier: "slowmode", text: (e) => e.systemMessage || "This room is now in slow mode." });
const SubOnlyModeLine = systemLine("SubOnlyModeLine", { icon: "lock", modifier: "subsonly", text: (e) => e.systemMessage || "This room is now in subscribers-only mode." });
const FollowerOnlyModeLine = systemLine("FollowerOnlyModeLine", { icon: "lock", modifier: "followersonly", text: (e) => e.systemMessage || "This room is now in followers-only mode." });
const EmoteOnlyModeLine = systemLine("EmoteOnlyModeLine", { icon: "emote", modifier: "emoteonly", text: (e) => e.systemMessage || "This room is now in emote-only mode." });
const R9KModeLine = systemLine("R9KModeLine", { icon: "lock", modifier: "r9k", text: (e) => e.systemMessage || "This room is now in unique-chat mode." });
const DisconnectedLine = systemLine("DisconnectedLine", { icon: "info", modifier: "disconnected", text: () => "Disconnected from chat" });
const ReconnectLine = systemLine("ReconnectLine", { icon: "info", modifier: "reconnect", text: () => "Reconnecting to chat" });
const WelcomeLine = systemLine("WelcomeLine", { icon: "info", modifier: "welcome", text: () => "Welcome to the chat room!" });

export function ConnectedLine(_props: LineProps<ChatNoticeEvent>) {
  return (
    <Layout padding={{ x: 1, y: 0.5 }} className="chat-line__status" data-a-target="chat-connected-line">
      <CoreText $fontSize={6} $color="alt-2">
        Welcome to the chat room!
      </CoreText>
    </Layout>
  );
}

export function LiveMessageSeparatorLine(_props: LineProps<ChatNoticeEvent>) {
  return (
    <Layout className="live-message-separator" display="flex" alignItems="center" padding={{ x: 1, y: 0.5 }}>
      <Layout className="live-message-separator__line" flexGrow={1} borderTop />
      <Layout padding={{ x: 1 }}>
        <CoreText $fontSize={7} $color="alt-2">
          Live
        </CoreText>
      </Layout>
      <Layout className="live-message-separator__line" flexGrow={1} borderTop />
    </Layout>
  );
}

export function ModerationLine({ message }: LineProps<ChatNoticeEvent>) {
  const duration = message.params["ban-duration"];
  let text = message.systemMessage;
  if (!text) text = duration ? `A user was timed out for ${duration} seconds.` : message.params["target-msg-id"] ? "A message was deleted." : "A user was banned.";
  return (
    <Layout padding={{ x: 1, y: 0.5 }} className="user-notice-line">
      <Layout className="user-notice-line__inner user-notice-line--moderation" data-a-target="chat-moderation-line" padding={{ left: 1 }} display="flex" alignItems="center">
        <Layout flexShrink={0} margin={{ right: 0.5 }}>
          <SvgIcon name="moderation" size={16} />
        </Layout>
        <CoreText $fontSize={6} $color="alt-2">
          {text}
        </CoreText>
      </Layout>
    </Layout>
  );
}

function simple(displayName: string, icon: IconName, modifier: string) {
  return systemLine(displayName, { icon, modifier });
}

