const TYPE_LINES: Partial<Record<ChatEventType, AnyLine>> = {
  [ChatEventType.Message]: MessageLine,
  [ChatEventType.Action]: MessageLine,
  [ChatEventType.Subscription]: SubscriptionLine,
  [ChatEventType.Resubscription]: ResubscriptionLine,
  [ChatEventType.SubGift]: SubGiftLine,
  [ChatEventType.SubMysteryGift]: SubMysteryGiftLine,
  [ChatEventType.GiftPaidUpgrade]: GiftPaidUpgradeLine,
  [ChatEventType.Raid]: RaidLine,
  [ChatEventType.Announcement]: AnnouncementLine,
  [ChatEventType.BitsBadgeTier]: BitsBadgeTierMessage,
  [ChatEventType.Ritual]: RitualLine,
  [ChatEventType.Notice]: NoticeLine,
  [ChatEventType.Moderation]: ModerationLine,
  [ChatEventType.ChatCleared]: ChatClearedLine,
  [ChatEventType.RoomMods]: RoomModsLine,
  [ChatEventType.SlowMode]: SlowModeLine,
  [ChatEventType.SubsOnlyMode]: SubOnlyModeLine,
  [ChatEventType.FollowersOnlyMode]: FollowerOnlyModeLine,
  [ChatEventType.EmoteOnlyMode]: EmoteOnlyModeLine,
  [ChatEventType.R9KMode]: R9KModeLine,
  [ChatEventType.Connected]: ConnectedLine,
  [ChatEventType.Disconnected]: DisconnectedLine,
  [ChatEventType.Reconnect]: ReconnectLine,
  [ChatEventType.LiveSeparator]: LiveMessageSeparatorLine,
  [ChatEventType.Welcome]: WelcomeLine,
};

export function lineComponentFor(message: ChatMessageEvent | ChatNoticeEvent): AnyLine {
  if (message.type !== ChatEventType.Message && message.type !== ChatEventType.Action && message.msgId) {
    const byMsgId = MSG_ID_LINES[message.msgId];
    if (byMsgId) return byMsgId;
  }
  return TYPE_LINES[message.type] ?? (NoticeLine);
}

export function lineTypeCount(): number {
  return new Set([...Object.values(MSG_ID_LINES), ...Object.values(TYPE_LINES)]).size;
}

/** The innermost component of the line HOC stack: picks the line component for the event. */
export function LineDispatcher(props: LineProps) {
  const Line = lineComponentFor(props.message as ChatMessageEvent | ChatNoticeEvent);
  return (
    <LineErrorBoundary>
      <Line {...(props as LineProps<never>)} />
    </LineErrorBoundary>
  );
}
LineDispatcher.displayName = "LineDispatcher";
