import { registerGqlResolver } from "./fake-gql";
import { workloadData } from "../platform/data";

registerGqlResolver("ChatBadges", () => {
  const badges = [];
  for (const [setID, versions] of Object.entries(workloadData().badges)) {
    for (const [version, { title }] of Object.entries(versions)) {
      badges.push({ __typename: "Badge", id: `${setID}/${version}`, setID, version, title });
    }
  }
  return { badges };
});
