import { gql } from "@apollo/client";

export const ChatBadgesQuery = gql`
  query ChatBadges($channelLogin: String!) {
    badges(channelLogin: $channelLogin) {
      id
      setID
      version
      title
    }
  }
`;

export const ChatLineUserQuery = gql`
  query ChatLineUser($userID: ID!) {
    user(id: $userID) {
      id
      displayName
      login
      chatColor
    }
  }
`;

export interface ChatBadgesData {
  badges: { id: string; setID: string; version: string; title: string; __typename: "Badge" }[];
}
