import styled, { css } from "styled-components";
import type { DefaultTheme } from "styled-components";

export type TextColor = "base" | "alt" | "alt-2" | "link" | "error" | "warn" | "brand" | "inherit";
type FontSize = 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8;

interface TextProps {
  $color?: TextColor;
  $fontSize?: FontSize;
  $bold?: boolean;
  $ellipsis?: boolean;
  $lineClamp?: number;
  $align?: "left" | "center" | "right";
}

const colorOf = (theme: DefaultTheme, c: TextColor | undefined) => {
  switch (c) {
    case "alt": return theme.colors.textAlt;
    case "alt-2": return theme.colors.textAlt2;
    case "link": return theme.colors.link;
    case "error": return theme.colors.error;
    case "warn": return theme.colors.warn;
    case "brand": return theme.colors.brand;
    case "inherit": return "inherit";
    default: return theme.colors.text;
  }
};

const textStyles = css<TextProps>`
  color: ${({ theme, $color }) => colorOf(theme, $color)};
  font-size: ${({ theme, $fontSize }) => theme.fontSizes[$fontSize ?? 6]};
  ${({ $bold }) => $bold && "font-weight: 600;"}
  ${({ $align }) => $align && `text-align: ${$align};`}
  ${({ $ellipsis }) => $ellipsis && "overflow: hidden; text-overflow: ellipsis; white-space: nowrap;"}
  ${({ $lineClamp }) => $lineClamp && `display: -webkit-box; -webkit-line-clamp: ${$lineClamp}; -webkit-box-orient: vertical; overflow: hidden;`}
`;

export const CoreText = styled.p<TextProps>`
  margin: 0;
  line-height: 1.5;
  ${textStyles}
`;

export const Title = styled.h4.attrs<TextProps>((p) => ({ $bold: p.$bold ?? true, $fontSize: p.$fontSize ?? 5 }))<TextProps>`
  margin: 0;
  line-height: 1.2;
  ${textStyles}
`;
