import { useContext, type ComponentType, type Context } from "react";

/** Right-to-left function composition, as `redux.compose`. */
export { compose } from "redux";

/**
 * A higher-order component that reads `context` and passes its value down as
 * `propName`. The wrapper is a plain function component, so, like Twitch's
 * context HOCs, it re-renders whenever its parent does.
 */
export function withContextProp<V>(wrapperName: string, context: Context<V>, propName: string) {
  return function wrap<P extends object>(Wrapped: ComponentType<P>): ComponentType<Omit<P, typeof propName>> {
    const WithContext = (props: Omit<P, typeof propName>) => {
      const value = useContext(context);
      const forwarded = { ...props, [propName]: value } as P;
      return <Wrapped {...forwarded} />;
    };
    WithContext.displayName = `${wrapperName}(${Wrapped.displayName ?? Wrapped.name ?? "Component"})`;
    return WithContext as ComponentType<Omit<P, typeof propName>>;
  };
}
