import { Component, createRef, useState, type ReactNode, type TouchEvent } from "react";
import styled from "styled-components";
import { CoreButton, CoreText, Layout, SvgIcon } from "../core-ui";
import { emitStepEvent } from "../workload/events";
import { setInterval, clearInterval, setTimeout, clearTimeout } from "../platform/timers";
import { PauseReason, type MessageBufferAPI } from "./buffer-api";
import { ChatAreaScrollContext, type ChatScrollContextValue } from "./contexts";

const SCROLL_EVENTS = ["wheel", "mousewheel", "touchmove"] as const;
const PAUSE_DISTANCE = 10;

export interface MessageHandlerAPI {
  addMessageHandler(handler: () => void): void;
  removeMessageHandler(handler: () => void): void;
}

interface ResizeDetectorProps {
  onResize: () => void;
}

const ResizeFrame = styled.div`
  position: absolute;
  inset: 0;
  pointer-events: none;
  visibility: hidden;
`;

/** Calls `onResize` when the size of the element changes. */
class ResizeDetector extends Component<ResizeDetectorProps> {
  frame = createRef<HTMLDivElement>();
  observer: ResizeObserver | null = null;
  componentDidMount() {
    this.observer = new ResizeObserver(() => this.props.onResize());
    if (this.frame.current) this.observer.observe(this.frame.current);
  }
  componentWillUnmount() {
    this.observer?.disconnect();
  }
  render() {
    return <ResizeFrame ref={this.frame} aria-hidden="true" />;
  }
}

interface FooterProps {
  reason: PauseReason | null;
  unreadCount: number;
  secondsRemaining: number;
  onClick: () => void;
}

function footerText(props: FooterProps, hovered: boolean): string {
  if (hovered && props.reason === PauseReason.Scroll) {
    if (props.unreadCount === 0) return "See new messages";
    return props.unreadCount > 20 ? "20+ new messages" : props.unreadCount === 1 ? "1 new message" : `${props.unreadCount} new messages`;
  }
  if (props.reason === PauseReason.Mouseover) return "Chat paused due to mouseover";
  if (props.reason === PauseReason.AltKey) return "Chat paused with the Alt key";
  return "Chat paused due to scroll";
}

export function ChatPausedFooter(props: FooterProps) {
  const [hovered, setHovered] = useState(false);
  return (
    <Layout
      className="chat-paused-footer"
      data-a-target="chat-paused-footer"
      attachBottom
      background="overlay"
      margin={{ bottom: 1 }}
      position="absolute"
      borderRadius="rounded"
    >
      <CoreButton variant="text" overlay fullWidth onClick={(e) => (e.stopPropagation(), props.onClick())} onMouseEnter={() => setHovered(true)} onMouseLeave={() => setHovered(false)}>
        <Layout className="chat-paused-footer--button" display="flex" alignItems="center">
          <Layout margin={{ right: 0.5 }} display="flex">
            <SvgIcon name={hovered ? "arrowDown" : "pause"} size={16} />
          </Layout>
          <Layout maxWidth="27.3rem">
            <CoreText $fontSize={5} data-a-target="chat-list-footer-text">
              {footerText(props, hovered)}
            </CoreText>
          </Layout>
        </Layout>
      </CoreButton>
    </Layout>
  );
}
ChatPausedFooter.displayName = "ChatPausedFooter";

export interface ChatScrollerProps {
  buffer: MessageBufferAPI;
  messageHandlerAPI: MessageHandlerAPI;
  messagesHash: string;
  children: ReactNode;
}

interface ChatScrollerState {
  isPaused: boolean;
  reason: PauseReason | null;
  unreadCount: number;
  hoverResumeInterval: number | null;
  hoverResumeSecondsRemaining: number;
  openMenuMessageId: string | null;
}

/** The scrolling area of the chat list: keeps the newest line in view and pauses on user scrolling. */
export class ChatScroller extends Component<ChatScrollerProps, ChatScrollerState> {
  state: ChatScrollerState = {
    isPaused: false,
    reason: null,
    unreadCount: 0,
    hoverResumeInterval: null,
    hoverResumeSecondsRemaining: 5,
    openMenuMessageId: null,
  };

  scrollRef: HTMLDivElement | null = null;
  touchTimers = new Map<number, number>();

  componentDidMount() {
    this.props.messageHandlerAPI.addMessageHandler(this.onMessage);
  }

  componentWillUnmount() {
    this.props.messageHandlerAPI.removeMessageHandler(this.onMessage);
    this.removeScrollListeners();
    this.clearHoverResumeInterval();
    this.touchTimers.forEach((t) => clearTimeout(t));
    this.touchTimers.clear();
  }

  componentDidUpdate(prevProps: ChatScrollerProps, prevState: ChatScrollerState) {
    if (this.props.messagesHash !== prevProps.messagesHash && !this.state.isPaused && !this.state.openMenuMessageId) this.scrollToBottom();
    if (this.state.isPaused && !prevState.isPaused) emitStepEvent("chat-paused");
    else if (!this.state.isPaused && prevState.isPaused) emitStepEvent("chat-resumed");
  }

  saveScrollRef = (el: HTMLDivElement | null) => {
    if (el === null) this.removeScrollListeners();
    this.scrollRef = el;
    if (el) for (const type of SCROLL_EVENTS) el.addEventListener(type, this.handleScrollEvent, { passive: true });
  };

  removeScrollListeners() {
    if (this.scrollRef) for (const type of SCROLL_EVENTS) this.scrollRef.removeEventListener(type, this.handleScrollEvent);
  }

  handleScrollEvent = () => {
    const el = this.scrollRef;
    if (!el) return;
    const { scrollHeight, scrollTop, offsetHeight } = el;
    const distance = scrollHeight - scrollTop - offsetHeight;
    if (this.state.openMenuMessageId) return;
    if (this.state.isPaused) {
      this.clearHoverResumeInterval();
      if (distance <= PAUSE_DISTANCE) this.resume();
    } else if (distance > PAUSE_DISTANCE) this.pause(PauseReason.Scroll);
  };

  handleResize = () => {
    if (!this.state.isPaused) this.scrollToBottom();
  };

  scrollToBottom = () => {
    const el = this.scrollRef;
    if (!el) return;
    const { scrollHeight, scrollTop, offsetHeight } = el;
    if (scrollHeight - scrollTop - offsetHeight > 0) el.scrollTop = scrollHeight;
  };

  pause = (reason: PauseReason = PauseReason.Scroll) => {
    if (this.state.isPaused) return;
    this.setState({ isPaused: true, reason }, () => this.props.buffer.pause(reason));
  };

  resume = () => {
    this.props.buffer.loadNewest();
    this.clearHoverResumeInterval();
    if (this.state.isPaused) this.setState({ isPaused: false, reason: null, unreadCount: 0 });
  };

  onFooterClick = () => {
    this.resume();
    this.scrollToBottom();
  };

  onMessage = () => {
    if (this.state.isPaused) this.setState((s) => ({ unreadCount: s.unreadCount + 1 }));
  };

  hoverPause = () => {
    if (this.state.isPaused || this.state.openMenuMessageId) return;
    this.setState({ hoverResumeInterval: setInterval(this.onHoverResumeInterval, 1000) });
    this.pause(PauseReason.Mouseover);
  };

  hoverResume = () => {
    if (this.state.isPaused && this.state.hoverResumeInterval !== null) this.resume();
  };

  onHoverResumeInterval = () => {
    if (this.state.hoverResumeSecondsRemaining > 1) this.setState((s) => ({ hoverResumeSecondsRemaining: s.hoverResumeSecondsRemaining - 1 }));
    else this.resume();
  };

  clearHoverResumeInterval = () => {
    if (this.state.hoverResumeInterval !== null) {
      clearInterval(this.state.hoverResumeInterval);
      this.setState({ hoverResumeInterval: null, hoverResumeSecondsRemaining: 5 });
    }
  };

  longPressPause = (e: TouchEvent) => {
    const touch = e.touches[0];
    if (!touch || this.state.isPaused) return;
    this.touchTimers.set(
      touch.identifier,
      setTimeout(() => this.pause(PauseReason.Scroll), 500),
    );
  };

  longPressResume = (e: TouchEvent) => {
    for (const touch of Array.from(e.changedTouches)) {
      const timer = this.touchTimers.get(touch.identifier);
      if (timer !== undefined) {
        clearTimeout(timer);
        this.touchTimers.delete(touch.identifier);
      }
    }
  };

  contextValue: ChatScrollContextValue = {
    pause: () => this.pause(PauseReason.Scroll),
    resume: this.resume,
    scrollToBottom: () => {
      if (!this.state.isPaused) this.scrollToBottom();
    },
    setOpenMenuMessageId: (id) => {
      this.setState({ openMenuMessageId: id });
      if (id && !this.state.isPaused) this.pause(PauseReason.Scroll);
    },
  };

  render() {
    const { isPaused, reason, unreadCount, hoverResumeSecondsRemaining } = this.state;
    return (
      <ChatAreaScrollContext.Provider value={this.contextValue}>
        <Layout display="flex" flexDirection="column" overflow="hidden" flexGrow={1} className="chat-scrollable-area__root">
          <Layout
            position="relative"
            className="chat-list--default"
            flexGrow={1}
            onMouseEnter={this.hoverPause}
            onMouseLeave={this.hoverResume}
            onTouchStart={this.longPressPause}
            onTouchEnd={this.longPressResume}
            onTouchCancel={this.longPressResume}
          >
            <ResizeDetector onResize={this.handleResize} />
            <div data-a-target="chat-scroller" className="scrollbar-wrapper chat-scrollable-area">
              <div className="scrollable-area" data-test-selector="scrollable-area-wrapper" ref={this.saveScrollRef}>
                <Layout className={isPaused ? "chat-scrollable-area__message-container chat-scrollable-area__message-container--paused" : "chat-scrollable-area__message-container"} data-test-selector="chat-scrollable-area__message-container" flexGrow={1}>
                  {this.props.children}
                </Layout>
              </div>
            </div>
            {isPaused ? <ChatPausedFooter reason={reason} unreadCount={unreadCount} secondsRemaining={hoverResumeSecondsRemaining} onClick={this.onFooterClick} /> : null}
          </Layout>
        </Layout>
      </ChatAreaScrollContext.Provider>
    );
  }
}
