import { Avatar, ButtonIcon, CoreText, Layout, Title } from "../core-ui";
import { useChatUiStore } from "./chat-ui-store";

/** Mounted only while a username has been clicked. */
export function ViewerCard() {
  const userID = useChatUiStore((s) => s.viewerCardUserID);
  const anchor = useChatUiStore((s) => s.viewerCardAnchor);
  const close = useChatUiStore((s) => s.closeViewerCard);
  if (!userID || !anchor) return null;
  return (
    <Layout
      className="viewer-card"
      data-a-target="viewer-card"
      position="fixed"
      background="overlay"
      borderRadius="medium"
      elevation
      padding={1}
      width="30rem"
      zIndex={9000}
      style={{ left: Math.max(8, anchor.x - 100), top: anchor.y + 4 }}
    >
      <Layout display="flex" alignItems="center">
        <Avatar alt={`User ${userID}`} size={40} userLogin={userID} />
        <Layout flexGrow={1} margin={{ left: 1 }}>
          <Title>User {userID}</Title>
          <CoreText $fontSize={7} $color="alt-2">
            Viewer card
          </CoreText>
        </Layout>
        <ButtonIcon icon="close" size="small" aria-label="Close" onClick={close} />
      </Layout>
    </Layout>
  );
}
