import { cloneElement, useCallback, useRef, useState, type ReactElement, type ReactNode } from "react";
import styled from "styled-components";
import { InjectLayout } from "./layout";
import { setTimeout, clearTimeout } from "../platform/timers";

const TipBubble = styled.div<{ $placement: "top" | "bottom" }>`
  position: absolute;
  ${({ $placement }) => ($placement === "top" ? "bottom: calc(100% + 0.6rem);" : "top: calc(100% + 0.6rem);")}
  left: 50%;
  transform: translateX(-50%);
  z-index: 9000;
  padding: 0.4rem 0.8rem;
  border-radius: ${({ theme }) => theme.radii.medium};
  background: ${({ theme }) => theme.colors.text};
  color: ${({ theme }) => theme.colors.base};
  font-size: ${({ theme }) => theme.fontSizes[6]};
  white-space: nowrap;
  pointer-events: none;
`;

function TooltipLayer({ open, label, placement }: { open: boolean; label: ReactNode; placement: "top" | "bottom" }) {
  if (!open) return null;
  return (
    <TipBubble role="tooltip" $placement={placement}>
      {label}
    </TipBubble>
  );
}

export interface TooltipProps {
  label: ReactNode;
  placement?: "top" | "bottom";
  children: ReactElement;
}

/** Wraps its child in an inline-block target; the tip is mounted only while the pointer is over it. */
export function Tooltip({ label, placement = "top", children }: TooltipProps) {
  const [open, setOpen] = useState(false);
  const timer = useRef<number | undefined>(undefined);
  const show = useCallback(() => {
    clearTimeout(timer.current);
    timer.current = setTimeout(() => setOpen(true), 150);
  }, []);
  const hide = useCallback(() => {
    clearTimeout(timer.current);
    setOpen(false);
  }, []);
  return (
    <>
      <InjectLayout display="inline-block" position="relative">
        <div className="tw-tooltip-wrapper" onMouseEnter={show} onMouseLeave={hide} onFocus={show} onBlur={hide}>
          {cloneElement(children)}
          <TooltipLayer open={open} label={label} placement={placement} />
        </div>
      </InjectLayout>
    </>
  );
}
