import { useCallback, useContext, useEffect, useMemo, useRef, useState } from "react";
import { useQuery } from "@apollo/client";
import { useSelector } from "react-redux";
import { ThemeContext } from "styled-components";
import { ButtonIcon, CoreText, Layout, ThemeProvider } from "../core-ui";
import { ChatBadgesQuery, type ChatBadgesData } from "../apollo/chat-queries";
import "../apollo/chat-resolvers";
import type { RootState } from "../state/store";
import { emitStepEvent } from "../workload/events";
import { ChatInput } from "./ChatInput";
import { ChatList } from "./ChatList";
import { ViewerCard } from "./ViewerCard";
import { useChatUiStore } from "./chat-ui-store";
import { getChatConnection } from "./connection";
import { createMessageBuffer } from "./message-buffer";
import { ChatContextProviders, type BadgeLookup, type ChatConfig } from "./contexts";
import type { MessageHandlerAPI } from "./ChatScroller";
import type { ChatEvent } from "./types";
import "./chat.css";

function useBadgeLookup(login: string): BadgeLookup {
  const { data } = useQuery<ChatBadgesData>(ChatBadgesQuery, { variables: { channelLogin: login } });
  return useMemo(() => {
    const titles = new Map<string, string>();
    for (const badge of data?.badges ?? []) titles.set(`${badge.setID}/${badge.version}`, badge.title);
    return { titleFor: (setID, version) => titles.get(`${setID}/${version}`) };
  }, [data]);
}

function ChatHeader() {
  return (
    <Layout className="stream-chat-header" display="flex" alignItems="center" justifyContent="center" padding={{ x: 1 }} position="relative" borderBottom>
      <Layout position="absolute" className="stream-chat-header__collapse" style={{ left: 4 }}>
        <ButtonIcon icon="chevron" size="small" aria-label="Collapse chat" iconSize={16} />
      </Layout>
      <CoreText $fontSize={5} $bold $align="center" className="stream-chat-header__title" data-a-target="stream-chat-header">
        Stream Chat
      </CoreText>
    </Layout>
  );
}

function ChatRoom({ login }: { login: string }) {
  const settings = useSelector((s: RootState) => s.chatSettings);
  const [buffer] = useState(() => createMessageBuffer(login));
  const handlers = useRef(new Set<() => void>());
  const joinedRef = useRef(false);
  const [joined, setJoined] = useState(false);
  const badges = useBadgeLookup(login);

  const messageHandlerAPI = useMemo<MessageHandlerAPI>(
    () => ({
      addMessageHandler: (h) => void handlers.current.add(h),
      removeMessageHandler: (h) => void handlers.current.delete(h),
    }),
    [],
  );

  useEffect(() => {
    const connection = getChatConnection();
    connection.join(login, (event: ChatEvent) => {
      buffer.handleEvent(event);
      handlers.current.forEach((h) => h());
      if (!joinedRef.current) {
        joinedRef.current = true;
        setJoined(true);
      }
    });
    return () => {
      connection.part(login);
      buffer.dispose();
    };
  }, [login, buffer]);

  useEffect(() => {
    if (joined) emitStepEvent("chat-joined");
  }, [joined]);

  const config = useMemo<ChatConfig>(
    () => ({
      channelLogin: login,
      channelID: login,
      fontSize: "medium",
      showTimestamps: settings.showTimestamps,
      showModIcons: false,
      readableColors: settings.highContrastUsernames,
      chatPerformanceFlag: false,
    }),
    [login, settings.showTimestamps, settings.highContrastUsernames],
  );
  const openReplyTray = useCallback((m: Parameters<ReturnType<typeof useChatUiStore.getState>["openReplyTray"]>[0]) => useChatUiStore.getState().openReplyTray(m), []);
  const openViewerCard = useCallback((id: string, anchor: { x: number; y: number }) => useChatUiStore.getState().openViewerCard(id, anchor), []);
  const replyTray = useMemo(() => ({ openReplyTray }), [openReplyTray]);
  const viewerCard = useMemo(() => ({ openViewerCard }), [openViewerCard]);

  return (
    <ChatContextProviders config={config} badges={badges} scroll={null} replyTray={replyTray} viewerCard={viewerCard}>
      <section className="chat-room" data-test-selector="chat-room-component-layout" data-a-target="chat-room" aria-label="Chat">
        <Layout className="chat-room__content" display="flex" flexDirection="column" fullHeight background="base">
          <ChatHeader />
          <Layout className="chat-room__list" display="flex" flexDirection="column" flexGrow={1} overflow="hidden" position="relative">
            <ChatList buffer={buffer} messageHandlerAPI={messageHandlerAPI} chatPerformanceFlag={config.chatPerformanceFlag} />
          </Layout>
          <ChatInput />
        </Layout>
        <ViewerCard />
      </section>
    </ChatContextProviders>
  );
}

/** The chat column of a channel page. Switching `login` tears the room down and joins the new channel. */
export function ChannelChat({ login }: { login: string }) {
  const hasTheme = useContext(ThemeContext) != null;
  const room = <ChatRoom key={login} login={login} />;
  return hasTheme ? room : <ThemeProvider>{room}</ThemeProvider>;
}
