// Chat UI state that lives outside Redux, as on Twitch: which viewer card and
// reply tray are open.
import { create } from "zustand";
import type { ChatMessageEvent } from "./types";

interface ChatUiState {
  viewerCardUserID: string | null;
  viewerCardAnchor: { x: number; y: number } | null;
  replyMessage: ChatMessageEvent | null;
  hoveredMessageId: string | null;
  openViewerCard: (userID: string, anchor: { x: number; y: number }) => void;
  closeViewerCard: () => void;
  openReplyTray: (message: ChatMessageEvent) => void;
  closeReplyTray: () => void;
  setHoveredMessage: (id: string | null) => void;
}

export const useChatUiStore = create<ChatUiState>((set) => ({
  viewerCardUserID: null,
  viewerCardAnchor: null,
  replyMessage: null,
  hoveredMessageId: null,
  openViewerCard: (userID, anchor) => set({ viewerCardUserID: userID, viewerCardAnchor: anchor }),
  closeViewerCard: () => set({ viewerCardUserID: null, viewerCardAnchor: null }),
  openReplyTray: (message) => set({ replyMessage: message }),
  closeReplyTray: () => set({ replyMessage: null }),
  setHoveredMessage: (id) => set({ hoveredMessageId: id }),
}));
