import { gql } from "@apollo/client";
import { graphql } from "@apollo/client/react/hoc";
import { connect } from "react-redux";
import { chatReplyTargetSet, type RootState } from "../state/store";
import {
  ChannelPointsContext,
  ChatAreaScrollContext,
  ChatConfigContext,
  ChatInputTrayDispatchContext,
  PinnedChatContext,
  ReplyHighlightContext,
  ReplyTrayContext,
  RewardRedemptionContext,
  SharedChatContext,
  ViewerCardContext,
} from "./contexts";
import { ChatLine } from "./ChatLine";
import { compose, withContextProp } from "./hocs";
import type { ComponentType } from "react";
import type { LineProps } from "./line-props";

const PinChatMessageMutation = gql`
  mutation PinChatMessage($channelID: ID!, $messageID: ID!) {
    pinChatMessage(input: { channelID: $channelID, messageID: $messageID }) {
      id
    }
  }
`;

const mapSettings = (state: RootState) => ({
  showTimestamps: state.chatSettings.showTimestamps,
  highContrast: state.chatSettings.highContrastUsernames,
  theme: state.chatSettings.theme,
});

const mapSession = (state: RootState) => ({ currentLogin: state.session.login });

/**
 * A normal chat message with the layers Twitch wraps around it: nine context
 * readers, a mutation HOC and two Redux connects, outermost first.
 */
export const MessageLine = compose(
  withContextProp("WithChatInputTrayDispatchContext", ChatInputTrayDispatchContext, "chatInputTray"),
  withContextProp("WithReplyTrayActions", ReplyTrayContext, "replyTray"),
  withContextProp("WithViewerCardContext", ViewerCardContext, "viewerCardContext"),
  graphql(PinChatMessageMutation, { name: "pinChatMessage" }),
  connect(mapSettings),
  connect(mapSession, { setReplyTarget: chatReplyTargetSet }),
  withContextProp("WithPinnedChatContext", PinnedChatContext, "pinnedChat"),
  withContextProp("WithChatConfigContext", ChatConfigContext, "chatConfig"),
  withContextProp("WithSharedChatContext", SharedChatContext, "sharedChat"),
  withContextProp("WithRewardRedemptionContext", RewardRedemptionContext, "rewardRedemption"),
  withContextProp("WithChannelPointsContext", ChannelPointsContext, "channelPoints"),
  withContextProp("WithChatAreaScrollContext", ChatAreaScrollContext, "chatScroll"),
  withContextProp("WithReplyHighlightContext", ReplyHighlightContext, "replyHighlight"),
)(ChatLine as never) as unknown as ComponentType<LineProps>;
