import { createContext, useMemo, type ReactNode } from "react";
import type { ChatMessageEvent } from "./types";

export interface ChatConfig {
  channelLogin: string;
  channelID: string;
  fontSize: "small" | "medium" | "large";
  showTimestamps: boolean;
  showModIcons: boolean;
  readableColors: boolean;
  chatPerformanceFlag: boolean;
}

export interface BadgeLookup {
  titleFor(setID: string, version: string): string | undefined;
}

export interface ChatScrollContextValue {
  pause(): void;
  resume(): void;
  scrollToBottom(): void;
  setOpenMenuMessageId(id: string | null): void;
}

export interface ReplyTrayContextValue {
  openReplyTray(message: ChatMessageEvent): void;
}

export interface ViewerCardContextValue {
  openViewerCard(userID: string, anchor: { x: number; y: number }): void;
}

export const ChatConfigContext = createContext<ChatConfig | null>(null);
export const ReplyTrayContext = createContext<ReplyTrayContextValue>({ openReplyTray() {} });
export const ViewerCardContext = createContext<ViewerCardContextValue>({ openViewerCard() {} });
export const PinnedChatContext = createContext<{ pinnedMessageId: string | null }>({ pinnedMessageId: null });
export const SharedChatContext = createContext<{ isSharedChat: boolean; sourceRoomIDs: readonly string[] }>({ isSharedChat: false, sourceRoomIDs: [] });
export const RewardRedemptionContext = createContext<{ highlightedRedemptionId: string | null }>({ highlightedRedemptionId: null });
export const ChannelPointsContext = createContext<{ pointsEnabled: boolean; pointsName: string }>({ pointsEnabled: false, pointsName: "Points" });
export const ChatAreaScrollContext = createContext<ChatScrollContextValue | null>(null);
export const ReplyHighlightContext = createContext<{ highlightedMessageId: string | null }>({ highlightedMessageId: null });
export const ChatInputTrayDispatchContext = createContext<{ dispatchTray(action: { type: string }): void }>({ dispatchTray() {} });
export const BadgeLookupContext = createContext<BadgeLookup>({ titleFor: () => undefined });
export const EmoteCardContext = createContext<{ showEmoteCard(emoteID: string, anchor: Element): void }>({ showEmoteCard() {} });
export const AnimationSettingContext = createContext<{ animate: boolean }>({ animate: true });
export const BitsConfigContext = createContext<{ tiers: readonly number[] }>({ tiers: [1, 100, 1000, 5000, 10000] });

export interface ChatContextsProps {
  config: ChatConfig;
  badges: BadgeLookup;
  scroll: ChatScrollContextValue | null;
  replyTray: ReplyTrayContextValue;
  viewerCard: ViewerCardContextValue;
  children: ReactNode;
}

/** Provides the context values the chat line HOC layers consume. All values are stable, so lines don't re-render for them. */
export function ChatContextProviders({ config, badges, scroll, replyTray, viewerCard, children }: ChatContextsProps) {
  const emoteCard = useMemo(() => ({ showEmoteCard() {} }), []);
  return (
    <ChatConfigContext.Provider value={config}>
      <BadgeLookupContext.Provider value={badges}>
        <ReplyTrayContext.Provider value={replyTray}>
          <ViewerCardContext.Provider value={viewerCard}>
            <ChatAreaScrollContext.Provider value={scroll}>
              <EmoteCardContext.Provider value={emoteCard}>{children}</EmoteCardContext.Provider>
            </ChatAreaScrollContext.Provider>
          </ViewerCardContext.Provider>
        </ReplyTrayContext.Provider>
      </BadgeLookupContext.Provider>
    </ChatConfigContext.Provider>
  );
}
